         themes=['Redemption: God rescues a people for himself', "God's name and presence: 'I AM WHO I AM' (3:14)", 'Covenant and law at Sinai', 'The tabernacle: God dwelling with his people'],
         key=['Exod 3:14', 'Exod 12:13', 'Exod 19:5-6', 'Exod 20:2-3', 'Exod 34:6-7', 'Exod 40:34'],
